from PyQt5 import QtWidgets, uic

epsilon = 0.000001

def verif(x):
    if len(x) != 0:
        p = 0
        i = -1
        ok = x[0] != "." and x[len(x) - 1] != "."
        for i in range(len(x)):
            if x[i] == ".":
                p += 1
        ok = ok and p <= 1

        while ok and i < len(x) - 1:
            i += 1
            ok = x[i] == "." or 0 <= int(x[i]) <= 9
        return ok
    else:
        return False

def factoriel(n):
    r = 1
    for i in range(1, n + 1):
        r *= i
    return r

def puissance(n, p):
    r = 1
    for i in range(p):
        r *= n
    return r
